-- ----------------------------
-- Table structure for ai_messages
-- ----------------------------
DROP TABLE IF EXISTS `ai_messages`;
CREATE TABLE `ai_messages`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '消息主键ID',
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'default' COMMENT '租户ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `conversation_id` bigint NOT NULL COMMENT '对话ID',
  `role` enum('user','assistant','system') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '消息角色：user=用户,assistant=AI,system=系统',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用户问题内容',
  `thinking_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'AI推理过程（深度思考内容）',
  `token_count` int NULL DEFAULT 0 COMMENT '消耗token数量（便于统计和计费）',
  `model` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'glm-5.1' COMMENT '使用的AI模型',
  `parent_message_id` bigint NULL DEFAULT NULL COMMENT '父消息ID（用于消息回复/threading）',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `ai_response` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'AI回复内容',
  `responded_at` datetime NULL DEFAULT NULL COMMENT 'AI回复时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_conversation`(`conversation_id` ASC) USING BTREE COMMENT '按对话查询索引',
  INDEX `idx_tenant_user`(`tenant_id` ASC, `user_id` ASC) USING BTREE COMMENT '按租户+用户查询索引',
  INDEX `idx_conversation_created`(`conversation_id` ASC, `created_at` ASC) USING BTREE COMMENT '按对话+创建时间排序索引',
  CONSTRAINT `fk_message_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `ai_conversations` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 37 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'AI对话消息表' ROW_FORMAT = Dynamic;

